/* ===== V123: ختام اليوم — يوميات العمال + تلف السمك + خلاصة اليوم ===== */
function dayKeyLocal(ts){ const d=new Date(ts); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0') }
function closeDayData(){
  const d0=new Date(); d0.setHours(0,0,0,0); const a=d0.getTime(), b=a+86400000;
  const ok=orders.filter(o=>o.ts>=a&&o.ts<b&&o.status!=='cancel');
  const S=k=>ok.reduce((s,o)=>s+(+o[k]||0),0);
  const D=settings.daily||{}, buys=[].concat(D.items||[],...((D.history||[]).map(h=>h.items||[]))).filter(e=>e.ts>=a&&e.ts<b);
  const waste=((settings.fish||{}).wasteLog||[]).filter(x=>x.ts>=a&&x.ts<b).reduce((s,x)=>s+(+x.kg||0),0);
  return {a,b,n:ok.length,sub:S('sub'),del:S('del'),dis:S('dis'),total:S('total'),buy:buys.reduce((s,e)=>s+(+e.cost||0),0),waste:Math.round(waste*100)/100};
}
function closeDay(){
  settings.workers=settings.workers||[]; settings.closings=settings.closings||[];
  const key=dayKeyLocal(Date.now()), old=settings.closings.find(c=>c.date===key);
  let ws=settings.workers.map(w=>{ const p=old&&old.wages.find(x=>x.name===w.name); return {name:w.name,wage:p?p.wage:(+w.wage||0),on:old?!!p:true} });
  const ov=document.createElement('div'); ov.className='ov';
  const draw=()=>{ const D=closeDayData(), wt=ws.filter(w=>w.on).reduce((s,w)=>s+(+w.wage||0),0), net=D.total-D.buy-wt;
    ov.innerHTML=`<div class="dlg od-dlg" role="dialog" aria-modal="true"><div class="dlg-t">ختام اليوم — ${new Date().toLocaleDateString('ar-IQ-u-nu-latn',{weekday:'long',day:'numeric',month:'numeric'})}</div>
      ${old?'<p class="note">هذا اليوم مختوم قبل، إذا تحفظ يتحدث.</p>':''}
      <div class="od-sec"><div class="od-r"><span>الطلبات</span><span>${fmt(D.n)}</span></div><div class="od-r"><span>قيمة الأكل</span><span>${fmt(D.sub)} د.ع</span></div><div class="od-r"><span>أجور التوصيل</span><span>${fmt(D.del)} د.ع</span></div>${D.dis?`<div class="od-r od-dis"><span>الخصومات</span><span>− ${fmt(D.dis)} د.ع</span></div>`:''}<div class="od-r od-tot"><span>الصافي المستلم</span><span>${fmt(D.total)} د.ع</span></div></div>
      <div class="od-sec"><b>السمك التالف اليوم: ${D.waste} كغم</b><div class="fcount-row"><input id="cdWaste" type="number" inputmode="decimal" min="0" step="0.5" placeholder="ضيف تلف (كغم)"><button class="btn-dark" id="cdWasteBtn" type="button">سجل تلف</button></div></div>
      <div class="od-sec"><div class="cd-wh"><b>يوميات العمال</b><button class="btn-sm" id="cdWEdit" type="button">الموظفين</button></div>
        ${ws.length?ws.map((w,i)=>`<label class="cd-w"><input type="checkbox" data-won="${i}" ${w.on?'checked':''}><span>${esc(w.name)}</span><input type="number" inputmode="numeric" min="0" step="1000" data-wage="${i}" value="${w.wage}" aria-label="يومية ${esc(w.name)}"></label>`).join(''):'<p class="note">ماكو موظفين. دوس "الموظفين" وضيفهم.</p>'}
        <div class="od-r"><span>مجموع اليوميات</span><span>${fmt(wt)} د.ع</span></div></div>
      <div class="od-sec"><div class="od-r"><span>المسواك اليوم</span><span>− ${fmt(D.buy)} د.ع</span></div><div class="od-r"><span>اليوميات</span><span>− ${fmt(wt)} د.ع</span></div><div class="od-r od-tot"><span>الربح بعد المصاريف</span><span style="color:${net<0?'#FF6B5E':'#4ADE80'}">${fmt(net)} د.ع</span></div></div>
      <div class="dlg-act"><button class="btn-main" id="cdSave">سجّل ختام اليوم</button><button class="btn-ghost" id="cdX">سكّر</button></div>
      ${(settings.closings||[]).length?`<div class="od-sec"><b>الختامات السابقة</b>${settings.closings.slice(-7).reverse().map(c=>`<div class="od-r"><span>${esc(c.date)}</span><span>صافي ${fmt(c.total)} · مسواك ${fmt(c.buy)} · يوميات ${fmt(c.wagesTotal)} · تلف ${c.waste} كغم · ربح ${fmt(c.profit)}</span></div>`).join('')}</div>`:''}</div>`;
    const rd=()=>{ ov.querySelectorAll('[data-won]').forEach(x=>ws[+x.dataset.won].on=x.checked); ov.querySelectorAll('[data-wage]').forEach(x=>ws[+x.dataset.wage].wage=Math.max(0,+x.value||0)) };
    ov.querySelectorAll('[data-won],[data-wage]').forEach(x=>x.addEventListener('change',()=>{ rd(); draw() }));
    ov.querySelector('#cdX').addEventListener('click',()=>ov.remove());
    ov.querySelector('#cdWasteBtn').addEventListener('click',()=>{ rd(); const v=parseFloat(ov.querySelector('#cdWaste').value); if(!(v>0)){ toast('اكتب كم كيلو تلف'); return }
      const f=settings.fish; f.wasteLog=(f.wasteLog||[]).concat([{ts:Date.now(),kg:v}]).slice(-200); f.used=Math.round(((f.used||0)+v)*100)/100;
      saveAll(); try{ fishCalc(); wasteRender() }catch(_){} toast('انسجل تلف '+v+' كغم'); draw() });
    ov.querySelector('#cdWEdit').addEventListener('click',()=>{ rd(); workersEdit(()=>{ ws=settings.workers.map(w=>{ const p=ws.find(x=>x.name===w.name); return p?{name:w.name,wage:p.wage,on:p.on}:{name:w.name,wage:+w.wage||0,on:true} }); draw() }) });
    ov.querySelector('#cdSave').addEventListener('click',()=>{ rd(); const D=closeDayData(), wages=ws.filter(w=>w.on).map(w=>({name:w.name,wage:+w.wage||0})), wt=wages.reduce((s,w)=>s+w.wage,0);
      const rec={date:key,ts:Date.now(),n:D.n,sub:D.sub,del:D.del,dis:D.dis,total:D.total,buy:D.buy,waste:D.waste,wages,wagesTotal:wt,profit:D.total-D.buy-wt};
      settings.closings=(settings.closings||[]).filter(c=>c.date!==key).concat([rec]).slice(-400);
      saveAll(); ov.remove(); toast('انسجل ختام اليوم'); try{ renderReport() }catch(_){} });
  };
  draw(); document.body.appendChild(ov);
}
function workersEdit(done){
  const ov=document.createElement('div'); ov.className='ov'; ov.style.zIndex=1001; let list=(settings.workers||[]).map(w=>({name:w.name,wage:+w.wage||0}));
  const draw=()=>{ ov.innerHTML=`<div class="dlg" role="dialog" aria-modal="true"><div class="dlg-t">الموظفين ويومياتهم</div>
    <div class="bw-list">${list.map((w,i)=>`<div class="fcount-row"><input data-n="${i}" value="${esc(w.name)}" aria-label="الاسم"><input data-w="${i}" type="number" inputmode="numeric" step="1000" value="${w.wage}" style="max-width:120px" aria-label="اليومية"><button class="btn-ghost" data-del="${i}" type="button">احذف</button></div>`).join('')||'<p class="note">بعد ما ضايف موظف.</p>'}</div>
    <div class="fcount-row" style="margin-top:10px"><input id="wkN" placeholder="اسم الموظف"><input id="wkW" type="number" inputmode="numeric" step="1000" placeholder="اليومية" style="max-width:120px"><button class="btn-dark" id="wkAdd" type="button">ضيف</button></div>
    <div class="dlg-act"><button class="btn-main" id="wkSave">احفظ</button><button class="btn-ghost" id="wkX">إلغاء</button></div></div>`;
    const rd=()=>{ ov.querySelectorAll('[data-n]').forEach(x=>{ const i=+x.dataset.n; list[i].name=x.value.trim(); list[i].wage=Math.max(0,+ov.querySelector('[data-w="'+i+'"]').value||0) }) };
    ov.querySelectorAll('[data-del]').forEach(b=>b.addEventListener('click',()=>{ rd(); list.splice(+b.dataset.del,1); draw() }));
    ov.querySelector('#wkAdd').addEventListener('click',()=>{ rd(); const n=ov.querySelector('#wkN').value.trim(); if(!n){ toast('اكتب الاسم'); return } list.push({name:n,wage:Math.max(0,+ov.querySelector('#wkW').value||0)}); draw() });
    ov.querySelector('#wkX').addEventListener('click',()=>ov.remove());
    ov.querySelector('#wkSave').addEventListener('click',()=>{ rd(); settings.workers=list.filter(w=>w.name); saveAll(); ov.remove(); toast('انحفظوا الموظفين'); done&&done() });
  };
  draw(); document.body.appendChild(ov);
}
document.getElementById('closeBtn').addEventListener('click',closeDay);
