    ...(()=>{ const C=(settings.closings||[]).filter(c=>c.ts>=R.a&&c.ts<R.b+86400000&&new Date(c.date+'T12:00').getTime()>=R.a&&new Date(c.date+'T12:00').getTime()<R.b); if(!C.length) return [];
